const DEG2RAD = Math.PI / 180;
const SCALE = 179.832710;
const OFFSET_X = 500.000000;
const OFFSET_Y = 286.470130;

export function projectLatLng(lat: number, lng: number): { x: number; y: number } {
  const lambda = lng * DEG2RAD;
  const phi = lat * DEG2RAD;
  const phi2 = phi * phi;
  const phi4 = phi2 * phi2;
  const rx =
    lambda *
    (0.8707 -
      0.131979 * phi2 +
      phi4 * (-0.013791 + phi4 * (0.003971 * phi2 - 0.001529 * phi4)));
  const ry =
    phi *
    (1.007226 +
      phi2 *
        (0.015085 + phi4 * (-0.044475 + 0.028874 * phi2 - 0.005916 * phi4)));
  return {
    x: rx * SCALE + OFFSET_X,
    y: -ry * SCALE + OFFSET_Y,
  };
}

